#[test]
fn check_order_before_the_batch_rules() {
    let mut h = Harness::new();
    for command in ["SendMessageBatch", "DeleteMessageBatch"] {
        let run = |h: &mut Harness, c: Value| error_code(&h.run(c)).to_owned();
        assert_eq!(run(&mut h, json!({"Command": command, "Entries": []})), "MissingParameter");
        assert_eq!(run(&mut h, json!({"Command": command, "QueueName": "q"})), "MissingParameter");
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": "q", "Entries": null})),
            "MissingParameter"
        );
        for bad in [json!("x"), json!({}), json!(5)] {
            assert_eq!(
                run(&mut h, json!({"Command": command, "QueueName": "q", "Entries": bad})),
                "InvalidParameterValue"
            );
        }
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": 5, "Entries": []})),
            "InvalidParameterValue"
        );
        // The queue lookup comes before the batch rules.
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": "q", "Entries": []})),
            "QueueDoesNotExist"
        );
    }
}

